    [11814]={name="Molten Fists",quality=3,ilvl=58,reqLevel=53,sourceType="boss_drop",instructions="Drops from Ambassador Flamelash.",zone="Blackrock Depths",npc="Ambassador Flamelash",lore="Ragnaros's envoy to the Dark Iron in Blackrock Depths, sent to keep the dwarves loyal to the Firelord."},
    [11815]={name="Hand of Justice",quality=3,ilvl=58,reqLevel=53,sourceType="boss_drop",instructions="Drops from Emperor Dagran Thaurissan.",zone="Blackrock Depths",npc="Emperor Dagran Thaurissan",lore="Prints five Strength and eight Stamina and is worth vastly more than that: the extra attack it grants is the reason a Blackrock Depths trinket stayed in raid sets for years."},
    [11816]={name="Angerforge's Battle Axe",quality=3,ilvl=56,reqLevel=51,sourceType="boss_drop",instructions="Drops from General Angerforge.",zone="Blackrock Depths",npc="General Angerforge",proc="Chance on hit: Deal 109 Physical damage. Trolls and Orcs take 2 times as much damage and are horrified for 4 sec."},
