    [12022]={name="Iridium Chain",quality=2,ilvl=41,reqLevel=36,sourceType="world_drop",instructions="World drop around level 36-42.",zone="Stranglethorn Vale"},
    [12026]={name="Quicksilver Pendant",quality=2,ilvl=59,reqLevel=54,sourceType="world_drop",instructions="World drop around level 38-61.",zone="Eastern Plaguelands"},
    [12040]={name="Forest Pendant",quality=2,ilvl=38,reqLevel=33,sourceType="world_drop",instructions="World drop around level 33-39.",zone="Stranglethorn Vale"},
    [12041]={name="Windshear Leggings",quality=3,ilvl=54,reqLevel=48,sourceType="quest_reward",instructions="Reward from the quest 'Abandoned Hope'. Pick it over the other reward choices. Starts with Marshal Windsor in Burning Steppes. Objective: Give Marshal Maxwell the bad news.",zone="Blackrock Depths",questName="Abandoned Hope",lore="Bolvar is a fool. I was gathering his precious 'proof' so that I could shove it down his throat. He is a blind buffoon. Proof stands two feet away from him and he does not see."},
    [12047]={name="Spectral Necklace",quality=2,ilvl=30,reqLevel=25,sourceType="world_drop",instructions="World drop around level 25-31.",zone="Stranglethorn Vale"},
    [12050]={name="Hazecover Boots",quality=2,ilvl=54,reqLevel=48,sourceType="quest_reward",instructions="Reward from the quest 'A Little Slime Goes a Long Way'. Pick it over the other reward choices. Starts with Laris Geardawdle in Ironforge. Objective: Bring 10 Filled Pure Sample Jars to Laris Geardawdle in Ironforge.If you have trouble finding them, perhaps try to get more clues from Laris.",zone="Ironforge",questName="A Little Slime Goes a Long Way",lore="I'm going to need more samples. But--and I don't know how to put this--they have to be pure samples. I know, I know. \"What does 'pure' mean, Laris?\" I'm not sure."},
